sys_script_include.script:
var PrefillCatalogItemUtils = Class.create();
PrefillCatalogItemUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	getPreviousRequestData: function() {
		var catItemId = this.getParameter('sysparm_Id');
		var result = {};
		var mtomGR = new GlideRecord('sc_item_option_mtom');
		mtomGR.addQuery('request_item', catItemId);
		// gs.error('sc_item_option_mtom record output' + catItemId);
		mtomGR.query();
		// gs.error('sc_item_option_mtom query1111' + mtomGR);
		// gs.error('mtomGR.sc_item_option1112' + mtomGR.sc_item_option);
		while (mtomGR.next()) {
		//	gs.error('mtomGR.sc_item_option1112' + mtomGR.sc_item_option);
			// gs.error('mtomGR.sc_item_option1112!!!' );
			var optionGR = new GlideRecord('sc_item_option');
			optionGR.get(mtomGR.sc_item_option);
			// gs.error('mtomGR.sc_item_option1113' + optionGR.value);
			result[optionGR.item_option_new.name +''] = optionGR.value + '';
		}
		var jsson = new global.JSON().encode(result);
		// gs.error('json:' + jsson);
		return jsson;
	},
    type: 'PrefillCatalogItemUtils'
});
